import { dgnrsFromChain, dgnrsToChain, isWholeDgnrsAmount } from './token-units.js';
import { walletAbi } from './wallet-abi.js';


// /app/app/sdgnrs.js — player-facing sDGNRS redemption burn.
//
// During a live game `burn(amount)` submits a delayed, RNG-priced redemption;
// after GAMEOVER it pays the deterministic proportional backing directly. The
// contract burns msg.sender's soulbound balance, so this action intentionally
// cannot use the app's delegated/operator acting-address path.
//
// Audit 01f11477c (run 65) keys redemptions by uint32 BATCH instead of day: a
// burn joins the open batch at any time, the next daily or mid-day RNG request
// closes and prices it (RedemptionBatchClosed), and the word answering that
// request rolls it 21-175% with one synthetic flip for its FLIP leg. Rows keep
// the `periodIndex` key name for the batch id.

import { sendTx, getProvider, ethers } from './contracts.js';
import { decodeRevertReason } from './reason-map.js';
import { CHAIN, CONTRACTS } from './chain-config.js';
import { get } from './store.js';
import { permissionlessReadProvider, readProviderBlockNumber } from './read-provider.js';
import { fetchJSON } from './api.js';
import { flipFromChain } from './token-units.js';

// Audit 01f11477c: uint32 batch keys. A claim is (tokens, activityScore + 1); the batch carries the
// close price (ethBase, flipEscrow for all its tokens) and, once resolved, its roll and synthetic
// flip. claimRedemption is the post-game-over claim (it also unwinds the batch still open then);
// live-game claims settle automatically. Burns are no longer blocked during RNG.
const SDGNRS_ABI = [
  'function burn(uint256 amount) external returns (uint256 ethOut, uint256 stethOut, uint256 flipOut)',
  'function burnWrapped(uint256 amount) external returns (uint256 ethOut, uint256 stethOut, uint256 flipOut)',
  'function previewBurnValue(uint256 amount) external view returns (uint256 ethOut, uint256 flipOut)',
  'function pendingRedemptions(address player, uint32 batchId) external view returns (uint128 tokens, uint16 activityScore)',
  'function redemptionBatches(uint32 batchId) external view returns (uint128 tokens, uint128 supplySnapshot, uint96 ethBase, uint96 flipEscrow, uint16 roll, uint16 flipReward)',
  'function redemptionBatchState() external view returns (uint32 openBatch, uint32 settlingBatch, uint32 cursor, uint256 escrowedSupply)',
  'function claimRedemption(address player, uint32 batchId) external',
  'event RedemptionSubmitted(address indexed player, uint256 sdgnrsAmount, uint32 indexed batchId)',
  'event RedemptionClaimed(address indexed player, uint32 indexed batchId, uint16 roll, uint256 ethPayout, uint256 lootboxEth, uint256 flipPaid)',
  'error Insufficient()',
  'error BurnTooSmall()',
  'error BurnsBlockedDuringLiveness()',
  'error ExceedsDailyRedemptionCap()',
  'error TransferFailed()',
  'error NotResolved()',
  'error NoClaim()',
  'error Unauthorized()',
  'error NotGameOver()',
  'error EndingPending()',
  'error RedemptionStageBlocked()',
];
const GAME_OVER_ABI = ['function gameOver() view returns (bool)'];
/** True for a redemption key (a uint32 batch id). */
export function isSdgnrsRedemptionKey(value) {
  const key = Number(value);
  return Number.isInteger(key) && key >= 0 && key <= 0xFFFFFFFF;
}

export const MIN_SDGNRS_BURN_WEI = 10n ** 18n;
export const MIN_DGNRS_BURN_WEI = MIN_SDGNRS_BURN_WEI;
export const SDGNRS_REDEMPTION_SUBMITTED_EVENT = 'degenerus:sdgnrs-redemption-submitted';
export const SDGNRS_BURN_DIALOG_REQUEST_EVENT = 'degenerus:open-sdgnrs-burn';
export const SDGNRS_CHARITY_VOTE_DIALOG_REQUEST_EVENT = 'degenerus:open-sdgnrs-charity-vote';
export const SDGNRS_REDEMPTION_LOOKBACK_BLOCKS = 120_000;
const SDGNRS_LOG_CHUNK_BLOCKS = 5_000;
const SDGNRS_REORG_OVERLAP_BLOCKS = 12;
// A dead/old API must not get hammered every 30s poll, but a 404 also must
// not calcify into a permanent "route missing" verdict beyond this session.
const SDGNRS_REDEMPTION_API_FAILURE_MEMO_MS = 5 * 60 * 1000;

/** Compact a burned sDGNRS amount to at most two significant figures. */
export function formatSdgnrsRedemptionAmount(value) {
  let raw;
  try { raw = BigInt(value ?? 0); } catch (_e) { return '—'; }
  if (raw < 0n) raw = -raw;
  if (raw === 0n) return '0';
  const token = 10n ** 18n;
  if (raw < 10n * token) {
    const tenths = ((raw * 10n) + (token / 2n)) / token;
    return tenths % 10n === 0n
      ? String(tenths / 10n)
      : `${tenths / 10n}.${tenths % 10n}`;
  }
  let whole = (raw + (token / 2n)) / token;
  const digits = whole.toString().length;
  const quantum = digits > 2 ? 10n ** BigInt(digits - 2) : 1n;
  if (quantum > 1n) whole = ((whole + (quantum / 2n)) / quantum) * quantum;
  const units = [
    [10n ** 15n, 'Q'], [10n ** 12n, 'T'], [10n ** 9n, 'B'],
    [10n ** 6n, 'M'], [10n ** 3n, 'K'],
  ];
  const unit = units.find(([threshold]) => whole >= threshold);
  if (!unit) return whole.toLocaleString('en-US');
  const [divisor, suffix] = unit;
  const tenths = (whole * 10n) / divisor;
  return tenths < 100n && tenths % 10n !== 0n
    ? `${tenths / 10n}.${tenths % 10n}${suffix}`
    : `${whole / divisor}${suffix}`;
}

let _contractFactory = null;
let _gameFactory = null;
let _ifaceCache = null;
const _redemptionLogStates = new Map();
const _redemptionStateInflight = new Map();
let _fetch = fetchJSON;
const _redemptionApiFailureMemo = new Map();

/** Test-only contract-construction seam. */
export function __setContractFactoryForTest(factory) {
  _contractFactory = typeof factory === 'function' ? factory : null;
}

/** Test-only GAME (gameOver) read seam. */
export function __setGameFactoryForTest(factory) {
  _gameFactory = typeof factory === 'function' ? factory : null;
}

/** Test-only reset. */
export function __resetContractFactoryForTest() {
  _contractFactory = null;
  _gameFactory = null;
  _ifaceCache = null;
  _redemptionLogStates.clear();
  _redemptionStateInflight.clear();
  _fetch = fetchJSON;
  _redemptionApiFailureMemo.clear();
}

/** Test-only /player/:address/sdgnrs-redemptions fetch seam. */
export function __setSdgnrsFetcherForTest(fetcher) {
  _fetch = typeof fetcher === 'function' ? fetcher : fetchJSON;
}

function _readProvider() {
  return permissionlessReadProvider(getProvider());
}

function _abi() { return walletAbi(SDGNRS_ABI, abiSDGNRS); }

function _iface() {
  if (!_ifaceCache) _ifaceCache = new ethers.Interface(_abi());
  return _ifaceCache;
}

function _buildContract(signerOrProvider) {
  if (_contractFactory) return _contractFactory(signerOrProvider);
  return new ethers.Contract(CONTRACTS.SDGNRS, _abi(), signerOrProvider);
}

function _burnError(error, asset = 'sDGNRS') {
  const name = error?.revert?.name || error?.errorName || null;
  const local = {
    Insufficient: {
      code: 'Insufficient',
      userMessage: `Not enough ${asset} for that burn.`,
      recoveryAction: 'Lower the burn amount.',
    },
    BurnTooSmall: {
      code: 'BurnTooSmall',
      userMessage: `Minimum burn is 1 ${asset}.`,
      recoveryAction: `Enter at least 1 ${asset}.`,
    },
    BurnsBlockedDuringLiveness: {
      code: 'BurnsBlockedDuringLiveness',
      userMessage: `${asset} burns are paused during the game-over check.`,
      recoveryAction: 'Wait for the game state to settle.',
    },
    ExceedsDailyRedemptionCap: {
      code: 'ExceedsDailyRedemptionCap',
      userMessage: "That burn exceeds today's redemption limit.",
      recoveryAction: 'Lower the amount or try again tomorrow.',
    },
  }[name];
  const decoded = local || decodeRevertReason(error);
  const wrapped = new Error(decoded.userMessage || `${asset} burn failed.`);
  wrapped.code = decoded.code;
  wrapped.userMessage = decoded.userMessage;
  wrapped.recoveryAction = decoded.recoveryAction;
  wrapped.cause = error;
  return wrapped;
}

function _claimError(error) {
  const name = error?.revert?.name || error?.errorName || null;
  const local = {
    NotResolved: {
      code: 'NotResolved',
      userMessage: 'This sDGNRS redemption is still waiting for RNG.',
      recoveryAction: 'Try again after the next daily result.',
    },
    NoClaim: {
      code: 'NoClaim',
      userMessage: 'This sDGNRS redemption was already claimed.',
      recoveryAction: 'Open its saved result instead.',
    },
    Unauthorized: {
      code: 'Unauthorized',
      userMessage: 'This wallet cannot claim that sDGNRS redemption.',
      recoveryAction: 'Switch to the wallet that submitted it.',
    },
    NotGameOver: {
      code: 'NotGameOver',
      userMessage: 'Live sDGNRS redemptions settle automatically with Mine FLIP.',
      recoveryAction: 'Wait for the next Mine FLIP; the result appears here.',
    },
    EndingPending: {
      code: 'EndingPending',
      userMessage: 'The game is ending; this redemption settles at game over.',
      recoveryAction: 'Claim it once the game is over.',
    },
  }[name];
  const decoded = local || decodeRevertReason(error);
  const wrapped = new Error(decoded.userMessage || 'sDGNRS redemption claim failed.');
  wrapped.code = decoded.code;
  wrapped.userMessage = decoded.userMessage;
  wrapped.recoveryAction = decoded.recoveryAction;
  wrapped.cause = error;
  return wrapped;
}

function _sameAddress(a, b) {
  return String(a || '').toLowerCase() === String(b || '').toLowerCase();
}

/** Decode sDGNRS submit/claim events from a transaction receipt. */
export function parseSdgnrsRedemptionReceipt(receipt, playerFilter = null) {
  const submissions = [];
  const claims = [];
  if (!receipt || !Array.isArray(receipt.logs)) return { submissions, claims };
  const want = playerFilter ? String(playerFilter).toLowerCase() : null;
  for (const log of receipt.logs) {
    try {
      if (CONTRACTS.SDGNRS
        && String(log?.address || '').toLowerCase() !== String(CONTRACTS.SDGNRS).toLowerCase()) continue;
      const parsed = walletReceiptLog(log, _iface());
      if (!parsed) continue;
      const player = String(parsed.args.player ?? parsed.args[0] ?? '').toLowerCase();
      if (want && player !== want) continue;
      if (parsed.name === 'RedemptionSubmitted') {
        // A batch burn is priced only when its batch closes, so the event carries no ETH
        // value or FLIP escrow; `periodIndex` holds the batch id.
        submissions.push({
          player,
          sdgnrsAmount: dgnrsFromChain(parsed.args.sdgnrsAmount),
          periodIndex: Number(parsed.args.batchId),
          batchId: Number(parsed.args.batchId),
          transactionHash: String(receipt.hash || receipt.transactionHash || log.transactionHash || '').toLowerCase() || null,
        });
      } else if (parsed.name === 'RedemptionClaimed') {
        claims.push({
          player,
          batchId: Number(parsed.args.batchId),
          roll: Number(parsed.args.roll),
          ethPayout: BigInt(parsed.args.ethPayout),
          lootboxEth: BigInt(parsed.args.lootboxEth),
          flipPaid: flipFromChain(parsed.args.flipPaid),
          transactionHash: String(receipt.hash || receipt.transactionHash || log.transactionHash || '').toLowerCase() || null,
        });
      }
    } catch (_e) {
      // Foreign event — ignore without losing the rest of the receipt.
    }
  }
  return { submissions, claims };
}

/**
 * Audit 01f11477c: one claim in one batch. Before the batch closes it is unpriced and waits for the
 * next RNG request; once closed its share of the close price is fixed and its roll lands with the
 * word answering that request. Live, the miner settles a resolved claim automatically;
 * after game over the owner claims it (the batch still open then unwinds at the game-over price).
 */
async function _readBatchRedemptionState(contract, provider, player, batchId, overrides) {
  const [pending, batch, batchState] = await Promise.all([
    contract.pendingRedemptions(await readWalletId(player, { provider, blockTag: overrides[0]?.blockTag }), batchId, ...overrides),
    contract.redemptionBatches(batchId, ...overrides),
    contract.redemptionBatchState(...overrides),
  ]);
  const tokens = BigInt(pending?.tokens ?? pending?.[0] ?? 0);
  const activityScore = Number(pending?.activityScore ?? pending?.[1] ?? 0);
  const batchTokens = BigInt(batch?.tokens ?? batch?.[0] ?? 0);
  const ethBase = BigInt(batch?.ethBase ?? batch?.[2] ?? 0);
  const flipEscrowRaw = BigInt(batch?.flipEscrow ?? batch?.[3] ?? 0);
  const roll = Number(batch?.roll ?? batch?.[4] ?? 0);
  const flipReward = Number(batch?.flipReward ?? batch?.[5] ?? 0);
  const openBatch = Number(batchState?.openBatch ?? batchState?.[0] ?? 0);
  const exists = tokens > 0n;
  const open = batchId === openBatch;
  // The claim's pro-rata share of the batch's close price (0 while the batch is open).
  const share = (value) => (batchTokens > 0n ? (value * tokens) / batchTokens : 0n);
  const resolved = exists && roll > 0;
  let claimMethod = null;
  let settling = false;
  if (exists && (resolved || open)) {
    const over = await _readGameOver(provider, overrides);
    if (over) claimMethod = 'claimRedemption';
    else settling = resolved;
  }
  return {
    player: String(player).toLowerCase(),
    periodIndex: batchId,
    batchId,
    sdgnrsTokens: dgnrsFromChain(tokens),
    ethValueOwed: open ? null : share(ethBase),
    activityScore: activityScore > 0 ? activityScore - 1 : 0,
    flipEscrow: open ? null : flipFromChain(share(flipEscrowRaw)),
    roll,
    flipReward,
    open,
    exists,
    ready: claimMethod != null,
    settling,
    claimMethod,
  };
}

/** Read one exact redemption batch slot and its roll. */
export async function readSdgnrsRedemptionState({ player, periodIndex, fresh = false } = {}) {
  if (!player || periodIndex == null) return null;
  const period = Number(periodIndex);
  if (!isSdgnrsRedemptionKey(period)) return null;
  const provider = _readProvider();
  if (!provider) return null;
  const key = `${String(player).toLowerCase()}:${period}:${fresh ? 'fresh' : 'display'}`;
  if (_redemptionStateInflight.has(key)) return _redemptionStateInflight.get(key);
  const request = (async () => {
    try {
      const contract = _buildContract(provider);
      let blockTag = null;
      try {
        blockTag = await readProviderBlockNumber(provider, { maxAgeMs: fresh ? 0 : 500 });
      } catch (_e) { /* latest remains usable */ }
      const overrides = blockTag == null ? [] : [{ blockTag }];
      return await _readBatchRedemptionState(contract, provider, player, period, overrides);
    } catch (_e) {
      return null;
    }
  })().finally(() => {
    if (_redemptionStateInflight.get(key) === request) _redemptionStateInflight.delete(key);
  });
  _redemptionStateInflight.set(key, request);
  return request;
}

async function _readGameOver(provider, overrides = []) {
  try {
    const game = _gameFactory ? _gameFactory(provider) : new ethers.Contract(CONTRACTS.GAME, walletAbi(GAME_OVER_ABI, abiGAME), provider);
    return Boolean(await game.gameOver(...overrides));
  } catch (_e) {
    return false;
  }
}

function _redemptionLogKey(log) {
  const transactionHash = String(log?.transactionHash || '').toLowerCase();
  const blockNumber = Number(log?.blockNumber ?? 0);
  const logIndex = Number(log?.index ?? log?.logIndex ?? 0);
  return `${transactionHash || `block:${blockNumber}`}:${logIndex}`;
}

function _redemptionRangeRefused(error) {
  const message = [error?.message, error?.shortMessage, error?.error?.message,
    error?.info?.error?.message].filter(Boolean).join(' ');
  if (error?.name === 'AbortError' || error?.name === 'TimeoutError'
    || error?.code === 'TIMEOUT' || Number(error?.status ?? error?.info?.responseStatus) === 429
    || /rate.?limit|too many requests|requests? per|HTTP\s+(?:429|5\d\d)|timeout|timed out|unavailable/i.test(message)) return false;
  // A busy or unreachable provider says nothing about the query's range.
  // Only an explicit block-span/result-size refusal justifies smaller pages.
  return /block range|range.*(?:large|wide|limit|exceed)|(?:query|response|result).*(?:large|size|limit|exceed)|(?:more than|too many).*(?:logs|results)|(?:maximum|max|limit).*\bblocks\b/i.test(message);
}

async function _fetchRedemptionLogRange(provider, filter, fromBlock, toBlock) {
  if (fromBlock > toBlock) return { logs: [], completeThrough: toBlock };
  // The public endpoint caps log queries at 50,000 blocks. Page before
  // sending, rather than paying for a guaranteed 120,001-block refusal on
  // every cold wallet. Partial progress stops at the first missing page.
  if (toBlock - fromBlock >= 50_000) {
    const logs = [];
    let completeThrough = fromBlock - 1;
    for (let start = fromBlock; start <= toBlock; start += 50_000) {
      const end = Math.min(toBlock, start + 49_999);
      const page = await _fetchRedemptionLogRange(provider, filter, start, end);
      logs.push(...page.logs);
      completeThrough = page.completeThrough;
      if (page.error) return { logs, completeThrough, error: page.error };
      if (completeThrough < end) break;
    }
    return { logs, completeThrough };
  }
  try {
    const logs = await provider.getLogs({ ...filter, fromBlock, toBlock });
    if (!Array.isArray(logs)) throw new Error('Invalid redemption log response.');
    return { logs, completeThrough: toBlock };
  } catch (error) {
    if (!_redemptionRangeRefused(error) || toBlock - fromBlock < SDGNRS_LOG_CHUNK_BLOCKS) {
      return { logs: [], completeThrough: fromBlock - 1, error };
    }
    const logs = [];
    let completeThrough = fromBlock - 1;
    // Walk forward and stop on the first missing range. Advancing across a
    // failed middle chunk would make that gap permanent on the next poll.
    for (let start = fromBlock; start <= toBlock; start += SDGNRS_LOG_CHUNK_BLOCKS) {
      const end = Math.min(toBlock, start + SDGNRS_LOG_CHUNK_BLOCKS - 1);
      try {
        const chunk = await provider.getLogs({ ...filter, fromBlock: start, toBlock: end });
        if (!Array.isArray(chunk)) throw new Error('Invalid redemption log response.');
        logs.push(...chunk);
        completeThrough = end;
      } catch (error) {
        return { logs, completeThrough, error };
      }
    }
    return { logs, completeThrough };
  }
}

// Persisted mirror of a player's redemption-log window. Without it every page
// load re-paid the full 120,000-block chunked scan before the cursor went
// incremental; with it a reload pays only the reorg-overlap tail. Keyed on
// chain + SDGNRS address + deploy block so a redeploy busts it. Skipped
// entirely when a test contract factory is installed (fake providers must not
// meet a previous session's window).
function _redemptionLogStorageKey(stateKey) {
  return `sdgnrs-redemption-logs:v1:${CONTRACTS.SDGNRS}:${Number(CHAIN.deployBlock) || 0}:${stateKey}`;
}

function _reviveRedemptionLogState(stateKey, state) {
  try {
    if (typeof localStorage === 'undefined' || _contractFactory) return;
    const parsed = JSON.parse(localStorage.getItem(_redemptionLogStorageKey(stateKey)));
    if (!parsed
      || !Number.isSafeInteger(Number(parsed.lastScannedBlock))
      || !Array.isArray(parsed.logs)) return;
    state.lastScannedBlock = Number(parsed.lastScannedBlock);
    for (const log of parsed.logs) state.logs.set(_redemptionLogKey(log), log);
  } catch (_e) { /* corrupt/absent — cold scan as before */ }
}

function _persistRedemptionLogState(stateKey, state) {
  try {
    if (typeof localStorage === 'undefined' || _contractFactory) return;
    if (!Number.isSafeInteger(Number(state.lastScannedBlock))) return;
    localStorage.setItem(_redemptionLogStorageKey(stateKey), JSON.stringify({
      lastScannedBlock: state.lastScannedBlock,
      // Only what downstream touches: parseLog reads topics+data, dedupe and
      // pruning read transactionHash/blockNumber/index.
      logs: [...state.logs.values()].map((log) => ({
        blockNumber: Number(log?.blockNumber ?? 0),
        index: Number(log?.index ?? log?.logIndex ?? 0),
        transactionHash: log?.transactionHash ?? null,
        topics: Array.isArray(log?.topics) ? [...log.topics] : [],
        data: log?.data ?? '0x',
      })),
    }));
  } catch (_e) { /* quota/serialization — memory window still works */ }
}

async function _recentRedemptionLogs(provider, player) {
  if (!provider || typeof provider.getLogs !== 'function') throw new Error('Redemption history provider unavailable.');
  const head = Number(await readProviderBlockNumber(provider, { maxAgeMs: 0 }));
  if (!Number.isSafeInteger(head) || head < 0) throw new Error('Invalid redemption history head.');
  const floor = Math.max(
    Number(CHAIN.deployBlock) || 0,
    head - SDGNRS_REDEMPTION_LOOKBACK_BLOCKS,
  );
  if (floor > head) return [];
  const playerKey = await readWalletId(player, { provider, blockTag: head });
  if (!playerKey) return [];
  const submit = _iface().encodeFilterTopics(_iface().getEvent('RedemptionSubmitted'), [playerKey]);
  const claimed = _iface().encodeFilterTopics(_iface().getEvent('RedemptionClaimed'), [playerKey]);
  const topics = [[submit[0], claimed[0]], submit[1]];
  const filter = { address: CONTRACTS.SDGNRS, topics };
  const key = `${CHAIN.id}:${String(player).toLowerCase()}`;
  let state = _redemptionLogStates.get(key);
  if (!state) {
    state = { lastScannedBlock: null, logs: new Map(), pending: null };
    _reviveRedemptionLogState(key, state);
    _redemptionLogStates.set(key, state);
  }
  if (state.pending) return state.pending;

  const request = (async () => {
    if (state.lastScannedBlock === head) return [...state.logs.values()];
    if (state.lastScannedBlock != null && head < state.lastScannedBlock) {
      state.logs.clear();
      state.lastScannedBlock = null;
    }
    const fromBlock = state.lastScannedBlock == null
      ? floor
      : Math.max(floor, state.lastScannedBlock - SDGNRS_REORG_OVERLAP_BLOCKS + 1);
    const scanned = await _fetchRedemptionLogRange(provider, filter, fromBlock, head);
    if (scanned.completeThrough >= fromBlock) {
      for (const [logKey, log] of state.logs) {
        const blockNumber = Number(log?.blockNumber ?? 0);
        if (blockNumber < floor || (blockNumber >= fromBlock && blockNumber <= scanned.completeThrough)) state.logs.delete(logKey);
      }
      for (const log of scanned.logs) state.logs.set(_redemptionLogKey(log), log);
      state.lastScannedBlock = scanned.completeThrough;
      _persistRedemptionLogState(key, state);
    }
    // Keep completed pages, but never publish an incomplete scan as
    // successful empty discovery: the controller retains its durable rows.
    if (scanned.error) throw scanned.error;
    return [...state.logs.values()];
  })().finally(() => {
    if (state.pending === request) state.pending = null;
  });
  state.pending = request;
  return request;
}

/** `log.parsed` fast path first (API-sourced rows), raw ethers decode otherwise. */
function _parseRedemptionLog(log) {
  // API-sourced rows come from the chain layer, whose FLIP amounts are already token wei.
  if (log?.parsed) return log.parsed;
  let parsed;
  try { parsed = walletReceiptLog(log, _iface()); } catch (_e) { return null; }
  if (!parsed || parsed.name !== 'RedemptionClaimed') return parsed;
  // A raw log: flipPaid is raw (whole) FLIP.
  const args = Object.assign([...parsed.args], parsed.args.toObject(), { flipPaid: flipFromChain(parsed.args.flipPaid) });
  // flipPaid is arg 5 (the batch id sits in front of the roll).
  args[parsed.fragment.inputs.findIndex((input) => input.name === 'flipPaid')] = args.flipPaid;
  return { name: parsed.name, args };
}

function _redemptionApiFailedRecently(owner) {
  const expiresAt = _redemptionApiFailureMemo.get(owner);
  if (expiresAt == null) return false;
  if (Date.now() >= expiresAt) {
    _redemptionApiFailureMemo.delete(owner);
    return false;
  }
  return true;
}

/**
 * API-first redemption event read. Wraps each EventRow as the shape the
 * existing `_parseRedemptionLog` fast path already honors, so the discovery
 * fold below runs unchanged regardless of source. Returns null (never [])
 * on a remote API failure. Native-chain failures propagate: falling back to
 * another scan would repeat the same RPC work after its retries are exhausted.
 */
async function _apiRedemptionLogs(player) {
  const owner = String(player || '').toLowerCase();
  if (!owner || (CHAIN.readMode !== 'chain' && _redemptionApiFailedRecently(owner))) return null;
  try {
    const payload = await _fetch(`/player/${owner}/sdgnrs-redemptions`);
    if (!Array.isArray(payload?.events)) throw new Error('Invalid redemption history response.');
    const events = payload.events;
    return events.map((row) => ({
      parsed: { name: row?.name, args: row?.args || {} },
      blockNumber: Number(row?.blockNumber ?? 0),
      logIndex: Number(row?.logIndex ?? 0),
      transactionHash: row?.transactionHash ?? null,
      topics: [],
      data: '0x',
    }));
  } catch (error) {
    if (CHAIN.readMode === 'chain' || error?.name === 'AbortError') throw error;
    _redemptionApiFailureMemo.set(owner, Date.now() + SDGNRS_REDEMPTION_API_FAILURE_MEMO_MS);
    return null;
  }
}

async function _redemptionLogsFor(player) {
  const apiLogs = await _apiRedemptionLogs(player);
  if (apiLogs) return apiLogs;
  const provider = _readProvider();
  return _recentRedemptionLogs(provider, player);
}

/**
 * Discover recent submissions and already-claimed receipts for one player.
 * Exact pending/ready state is always re-read from the contract; logs only
 * identify which composite-keyed periods belong to the player.
 */
export async function discoverSdgnrsRedemptions({ player, periodIndexes = [] } = {}) {
  if (!player) return { periods: [], claims: [] };
  const logs = await _redemptionLogsFor(player);
  const playerKey = await readWalletId(player);
  const periods = new Map();
  const claims = [];
  for (const log of Array.isArray(logs) ? logs : []) {
    try {
      const parsed = _parseRedemptionLog(log);
      if (!parsed) continue;
      const rawOwner = parsed.args.player ?? parsed.args[0];
      const owner = !log.parsed && String(rawOwner) === String(playerKey) ? String(player).toLowerCase() : String(rawOwner ?? '').toLowerCase();
      if (!_sameAddress(owner, player)) continue;
      if (parsed.name === 'RedemptionSubmitted') {
        const periodIndex = Number(parsed.args.batchId);
        const rawAmount = BigInt(parsed.args.sdgnrsAmount ?? parsed.args[1] ?? 0);
        const amount = log.parsed ? rawAmount : dgnrsFromChain(rawAmount);
        periods.set(periodIndex, (periods.get(periodIndex) || 0n) + amount);
      } else if (parsed.name === 'RedemptionClaimed') {
        claims.push({
          player: owner,
          roll: Number(parsed.args.roll),
          ethPayout: BigInt(parsed.args.ethPayout),
          lootboxEth: BigInt(parsed.args.lootboxEth),
          flipPaid: BigInt(parsed.args.flipPaid),
          transactionHash: String(log.transactionHash || '').toLowerCase(),
          blockNumber: Number(log.blockNumber ?? 0),
          logIndex: Number(log.index ?? log.logIndex ?? 0),
        });
      }
    } catch (_e) { /* unknown log */ }
  }
  const wantedPeriods = new Set(periods.keys());
  for (const periodIndex of Array.isArray(periodIndexes) ? periodIndexes : []) {
    const period = Number(periodIndex);
    if (isSdgnrsRedemptionKey(period)) wantedPeriods.add(period);
  }
  const states = await Promise.all([...wantedPeriods].map(async (periodIndex) => {
    const state = await readSdgnrsRedemptionState({ player, periodIndex });
    // Unknown is not a cleared claim. Let the controller retain durable rows
    // until every requested slot has an authoritative answer.
    if (!state) throw new Error('Redemption state unavailable.');
    return { ...state, sdgnrsAmount: periods.has(periodIndex) ? periods.get(periodIndex) : null };
  }));
  return {
    periods: states.filter((state) => state?.exists),
    claims: claims.sort((a, b) => b.blockNumber - a.blockNumber || b.logIndex - a.logIndex),
  };
}

/**
 * Read the current proportional backing for an sDGNRS burn.
 *
 * During the live game `ethOut` estimates the ETH/stETH base: the burn is
 * priced when its batch closes and rolls 21%–175% (mean 98%).
 * `flipOut` is contingent backing and pays only when the resolving flip wins,
 * so callers should not fold it into the ETH expectation.
 *
 * @param {{amount: bigint|string|number, publicRead?: boolean}} args
 * @returns {Promise<{ethOut: bigint, flipOut: bigint}|null>}
 */
export async function previewSdgnrsBurn({ amount, publicRead: _publicRead = false } = {}) {
  let amountWei;
  try { amountWei = BigInt(amount); }
  catch (_e) { return null; }
  if (amountWei <= 0n) return null;

  const provider = _readProvider();
  if (!provider) return null;
  const result = await _buildContract(provider).previewBurnValue(dgnrsToChain(amountWei));
  return {
    ethOut: BigInt(result?.ethOut ?? result?.[0] ?? 0),
    // FLIP backing: whole FLIP on chain; token wei here.
    flipOut: flipFromChain(result?.flipOut ?? result?.[1] ?? 0),
  };
}

/**
 * Burn the connected signer's own sDGNRS balance.
 *
 * @param {{amount: bigint|string|number}} args
 * @returns {Promise<{receipt: import('ethers').TransactionReceipt, amount: bigint}>}
 */
export async function burnSdgnrs({ amount } = {}) {
  const connected = get('connected.address');
  if (!connected) throw new Error('Connect a wallet first.');
  const viewed = get('viewing.address');
  if (viewed && String(viewed).toLowerCase() !== String(connected).toLowerCase()) {
    throw new Error("sDGNRS burns must be signed from the token owner's view.");
  }

  let amountWei;
  try { amountWei = BigInt(amount); }
  catch (_e) { throw new Error('Enter a valid sDGNRS amount.'); }
  if (!isWholeDgnrsAmount(amountWei)) throw new Error('sDGNRS supports up to 12 decimal places.');
  if (amountWei < MIN_SDGNRS_BURN_WEI) {
    throw new Error('Minimum burn is 1 sDGNRS.');
  }

  try {
    const receipt = await sendTx(
      (freshSigner) => _buildContract(freshSigner).burn(dgnrsToChain(amountWei)),
      'Burn sDGNRS',
    );
    const { submissions } = parseSdgnrsRedemptionReceipt(receipt, connected);
    return { receipt, amount: amountWei, submissions };
  } catch (error) {
    if (error?.revert?.name || error?.errorName) throw _burnError(error);
    throw error;
  }
}

/**
 * Burn transferable DGNRS through the same sDGNRS redemption backing.
 * DGNRS and sDGNRS are one-for-one supply claims, but the live-game wrapper
 * path must burn the connected signer's DGNRS before the backing sDGNRS.
 *
 * @param {{amount: bigint|string|number}} args
 * @returns {Promise<{receipt: import('ethers').TransactionReceipt, amount: bigint}>}
 */
export async function burnDgnrs({ amount } = {}) {
  const connected = get('connected.address');
  if (!connected) throw new Error('Connect a wallet first.');
  const viewed = get('viewing.address');
  if (viewed && String(viewed).toLowerCase() !== String(connected).toLowerCase()) {
    throw new Error("DGNRS burns must be signed from the token owner's view.");
  }

  let amountWei;
  try { amountWei = BigInt(amount); }
  catch (_e) { throw new Error('Enter a valid DGNRS amount.'); }
  if (!isWholeDgnrsAmount(amountWei)) throw new Error('DGNRS supports up to 12 decimal places.');
  if (amountWei < MIN_DGNRS_BURN_WEI) {
    throw new Error('Minimum burn is 1 DGNRS.');
  }

  try {
    const receipt = await sendTx(
      (freshSigner) => _buildContract(freshSigner).burnWrapped(dgnrsToChain(amountWei)),
      'Burn DGNRS',
    );
    const { submissions } = parseSdgnrsRedemptionReceipt(receipt, connected);
    return { receipt, amount: amountWei, submissions };
  } catch (error) {
    if (error?.revert?.name || error?.errorName) throw _burnError(error, 'DGNRS');
    throw error;
  }
}

/**
 * Claim a post-game-over sDGNRS redemption by direct payment. Live-game redemptions
 * settle automatically in mineRun's Redemption stage.
 */
export async function claimSdgnrsRedemption({ player, periodIndex } = {}) {
  const owner = String(player || '').toLowerCase();
  const period = Number(periodIndex);
  if (!owner) throw new Error('Missing sDGNRS redemption owner.');
  if (!isSdgnrsRedemptionKey(period)) {
    throw new Error('Invalid sDGNRS redemption batch.');
  }

  const state = await readSdgnrsRedemptionState({ player: owner, periodIndex: period, fresh: true });
  if (state && !state.claimMethod) {
    const err = new Error(state.settling
      ? 'This sDGNRS redemption settles automatically with the next Mine FLIP.'
      : state.open
        ? 'This sDGNRS redemption is waiting for the next RNG request to price it.'
        : 'This sDGNRS redemption is still waiting for RNG.');
    err.code = state.settling ? 'RedemptionSettling' : 'NotResolved';
    err.userMessage = err.message;
    throw err;
  }
  const method = state?.claimMethod ?? 'claimRedemption';

  try {
    const receipt = await sendTx(
      async (freshSigner) => _buildContract(freshSigner)[method](await accountArg(owner), period),
      'Claim sDGNRS redemption',
    );
    const { claims } = parseSdgnrsRedemptionReceipt(receipt, owner);
    return { receipt, player: owner, periodIndex: period, claim: claims.at(-1) || null };
  } catch (error) {
    if (error?.revert?.name || error?.errorName) throw _claimError(error);
    throw error;
  }
}
